function draw(){
  ctx.clearRect(0,0,W,H);
  // ship
  ctx.fillStyle='#0af';
  ctx.fillRect(ship.x, ship.y, ship.w, ship.h);
  // meteors
  ctx.fillStyle='#a44';
  meteors.forEach(m=>{ ctx.beginPath(); ctx.arc(m.x+m.size/2, m.y+m.size/2, m.size/2,0,Math.PI*2); ctx.fill(); });
  // score
  ctx.fillStyle='#000';
  ctx.font='16px sans-serif';
  ctx.fillText('Score: '+Math.floor(elapsed),10,20);
  if(gameOver){
    ctx.fillStyle='rgba(0,0,0,0.5)';
    ctx.fillRect(0,0,W,H);
    ctx.fillStyle='#fff';
    ctx.font='30px sans-serif';
    ctx.fillText('Game Over',W/2-80,H/2);
  }
}

input.newString:
function draw(){
  // background gradient
  const bgGrad = ctx.createLinearGradient(0,0,0,H);
  bgGrad.addColorStop(0,'#001');
  bgGrad.addColorStop(1,'#000');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0,0,W,H);
  // star field (twinkling)
  ctx.fillStyle = '#fff';
  stars.forEach(s=>{
    const twinkle = Math.random()*0.5+0.5;
    ctx.globalAlpha = twinkle;
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.radius, 0, Math.PI*2);
    ctx.fill();
  });
  ctx.globalAlpha = 1.0;
  // ship (triangle)
  ctx.fillStyle = '#0af';
  ctx.beginPath();
  ctx.moveTo(ship.x, ship.y + ship.h);
  ctx.lineTo(ship.x + ship.w/2, ship.y);
  ctx.lineTo(ship.x + ship.w, ship.y + ship.h);
  ctx.closePath();
  ctx.fill();
  // meteors with gradient
  meteors.forEach(m=>{
    const grad = ctx.createRadialGradient(
      m.x + m.size/2, m.y + m.size/2, m.size*0.1,
      m.x + m.size/2, m.y + m.size/2, m.size/2
    );
    grad.addColorStop(0,'#faa');
    grad.addColorStop(1,'#800');
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.arc(m.x + m.size/2, m.y + m.size/2, m.size/2, 0, Math.PI*2);
    ctx.fill();
  });
  // score
  ctx.fillStyle='#fff';
  ctx.font='16px sans-serif';
  ctx.fillText('Score: '+Math.floor(elapsed),10,20);
  if(gameOver){
    ctx.fillStyle='rgba(0,0,0,0.7)';
    ctx.fillRect(0,0,W,H);
    ctx.fillStyle='#fff';
    ctx.font='30px sans-serif';
    ctx.fillText('Game Over',W/2-80,H/2);
  }
}

